Problem:
A florist can deliver their flowers either by car or by truck. A car can deliver 6 units of flowers and uses 10 units of gas. A truck can deliver 9 units of flowers and uses 14 units of gas. The florist needs to deliver at least 130 units of flowers. Additionally, the number of cars used must exceed the number of trucks used. How many of each should be used to minimize the total amount of gas used?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "cars",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "trucks",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "cars",
     "coef": 10.0
    },
    {
     "var": "trucks",
     "coef": 14.0
    }
   ]
  },
  "constraints": [
   {
    "name": "flower_delivery",
    "terms": [
     {
      "var": "cars",
      "coef": 6.0
     },
     {
      "var": "trucks",
      "coef": 9.0
     }
    ],
    "sense": ">=",
    "rhs": 130.0
   },
   {
    "name": "cars_exceed_trucks",
    "terms": [
     {
      "var": "cars",
      "coef": 1.0
     },
     {
      "var": "trucks",
      "coef": -1.0
     }
    ],
    "sense": ">=",
    "rhs": 1.0
   }
  ]
 },
 "facts": {
  "objective": 212.0,
  "values": {
   "cars": 10.0,
   "trucks": 8.0
  },
  "binding": [],
  "slack": {
   "flower_delivery": 2.0,
   "cars_exceed_trucks": 1.0
  },
  "shadow_prices": null
 }
}
